const leave = $input.first().json;
const frontendUrl = $env.FRONTEND_URL || 'https://approvehub.internalautomation.io.vn';

// Calculate days pending
const createdAt = new Date(leave.created_at || leave.createdAt || Date.now());
const now = new Date();
const daysPending = Math.floor((now - createdAt) / (1000 * 60 * 60 * 24));

// Generate fresh approval tokens (7 days valid)
const tokenData = {
  id: leave._id || leave.leaveId || leave.id,
  type: 'approval',
  action: 'approve',
  exp: Date.now() + 7 * 24 * 60 * 60 * 1000
};
const managerToken = Buffer.from(JSON.stringify(tokenData)).toString('base64');
const hrToken = Buffer.from(JSON.stringify({ ...tokenData, isHr: true })).toString('base64');

// Determine recipient: if leave > 3 days and has HR email, route to HR; otherwise manager
const isHrLeave = (leave.leave_days || leave.leaveDays || 0) > 3;
const hasHrEmail = !!(leave.hrEmail || leave.hr_email);

let recipientEmail = leave.managerEmail || leave.manager_email || '';
let recipientName = leave.managerName || leave.manager_name || 'Quan ly';
let approvalLink = `${frontendUrl}/approval-page.html?token=${encodeURIComponent(managerToken)}&hr=false`;
let recipientType = 'manager';

if (isHrLeave && hasHrEmail) {
  recipientEmail = leave.hrEmail || leave.hr_email;
  recipientName = 'Bo phan Nhan su';
  approvalLink = `${frontendUrl}/approval-page.html?token=${encodeURIComponent(hrToken)}&hr=true`;
  recipientType = 'hr';
}

const fmt = (d) => {
  if (!d) return '';
  const pd = new Date(d);
  if (isNaN(pd)) return d;
  return pd.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

return [{ json: {
  ...leave,
  leaveDateDisplay: fmt(leave.leave_date || leave.leaveDate || ''),
  daysPending,
  recipientEmail,
  recipientName,
  recipientType,
  approvalLink,
  managerApprovalLink: `${frontendUrl}/approval-page.html?token=${encodeURIComponent(managerToken)}&hr=false`,
  hrApprovalLink: `${frontendUrl}/approval-page.html?token=${encodeURIComponent(hrToken)}&hr=true`,
  frontendUrl
} }];

// 1. Lấy dữ liệu từ node đầu vào
const item = $input.first().json;

// 2. Gán các biến chính bằng cú pháp JavaScript chuẩn (${...})
const to = item.recipientEmail;
const subject = `[ApproveHub] NHẮC NHỞ: Đơn nghỉ phép từ ${item.employee_name} đang chờ 4+ ngày`;

// 3. Nội dung HTML với tiếng Việt có dấu và tông màu đỏ khẩn cấp (Urgent)
const htmlBody = `<!DOCTYPE html>
<html>
<head><meta charset="UTF-8">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  .container { font-family: 'Segoe UI', Tahoma, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e0e0e0; border-radius: 10px; overflow: hidden; }
  .header { background: linear-gradient(135deg, #e74c3c, #c0392b); color: white; padding: 24px; text-align: center; }
  .header h2 { font-size: 1.3rem; }
  .urgent-bar { background: #fff0f0; color: #c0392b; text-align: center; padding: 8px; font-weight: 700; font-size: 0.85rem; }
  .content { padding: 28px; text-align: left; }
  .badge { display: inline-block; padding: 5px 12px; background: #fee; color: #c0392b; border-radius: 20px; font-size: 0.78rem; font-weight: 700; text-transform: uppercase; }
  .details-table { width: 100%; margin: 16px 0; border-collapse: collapse; border: 1px solid #eee; border-radius: 8px; overflow: hidden; }
  .details-table td { padding: 12px 14px; border-bottom: 1px solid #f5f5f5; font-size: 0.9rem; }
  .details-table td:first-child { font-weight: 600; color: #555; width: 38%; background: #fafafa; }
  .cta-button { display: block; width: 100%; max-width: 240px; margin: 20px auto; padding: 14px 24px; background: linear-gradient(135deg, #e74c3c, #c0392b); color: white !important; text-align: center; border-radius: 8px; font-weight: 700; text-decoration: none; font-size: 0.95rem; }
  .days-badge { background: #f39c12; color: white; padding: 3px 10px; border-radius: 12px; font-size: 0.8rem; font-weight: 700; }
  .footer { background: #f8f9fa; padding: 18px 24px; text-align: center; font-size: 0.78rem; color: #999; }
</style>
</head>
<body>
<div class="container">
  <div class="urgent-bar">ĐƠN ĐANG CHỜ PHÊ DUYỆT QUÁ 3 NGÀY - CẦN XỬ LÝ NGAY</div>
  <div class="header"><h2>Nhắc nhở Phê duyệt Đơn nghỉ phép</h2></div>
  <div class="content">
    <p>Kính gửi <strong>${item.recipientName}</strong>,</p>
    <p style="margin-top:8px;">Có đơn nghỉ phép từ <strong>${item.employee_name}</strong> đang chờ bạn phê duyệt đã quá <span class="days-badge">${item.daysPending} ngày</span>.</p>

    <div style="text-align:center; margin:16px 0;"><span class="badge">Chờ Phê duyệt - Ưu tiên cao</span></div>

    <table class="details-table">
      <tr><td>Nhân viên</td><td><strong>${item.employee_name}</strong></td></tr>
      <tr><td>Phòng ban</td><td>${item.department}</td></tr>
      <tr><td>Ngày nghỉ</td><td>${item.leaveDateDisplay}</td></tr>
      <tr><td>Số ngày</td><td>${item.leave_days} ngày</td></tr>
      <tr><td>Lý do</td><td>${item.reason}</td></tr>
      <tr><td>Trạng thái</td><td>Đang chờ ${item.recipientType === 'hr' ? 'HR' : 'Quản lý'} phê duyệt</td></tr>
      <tr><td>Mã đơn</td><td>#${item._id || item.leaveId}</td></tr>
    </table>

    <a href="${item.approvalLink}" class="cta-button">Phê duyệt ngay</a>

    <p style="margin-top:14px; font-size:0.82rem; color:#999; text-align:center;">Link hết hạn sau 7 ngày. Vui lòng phê duyệt sớm nhất có thể để đảm bảo quyền lợi nhân viên.</p>
  </div>
  <div class="footer"><strong>ApproveHub</strong> - Low-code Automation System</div>
</div>
</body>
</html>`;

const backendUrl = item.backendUrl || 'http://backend:3001';

// 4. Trả về kết quả cuối cùng
return [{ 
  json: { 
    ...item, 
    _to: to, 
    _subject: subject, 
    _htmlBody: htmlBody, 
    backendUrl 
  } 
}];

